#!/usr/bin/env python3
"""Keep this fork replaying upstream, so cight's shadow record covers upstream's real PRs.

    python3 .github/cight/mirror.py [--dry-run] sync   # merge upstream main into main
    python3 .github/cight/mirror.py [--dry-run] prs    # mirror upstream's open PRs
    python3 .github/cight/mirror.py [--dry-run] all    # both (what the schedule runs)

Run from a clone of the fork (`origin`), with `gh` signed in as the mirror's GitHub App.

- **main** = upstream main merged in (never rebased: upstream's commits keep their SHAs, so
  merge bases and maps line up with upstream history), with .github/workflows/test.yml
  regenerated by workflow.py on every merge. A push to main maps.
- **mirror/pr-<N>** = main merged with upstream PR N's head, opened as a PR here. Its diff
  against main is the upstream change, so test.yml's pre-job and cight see what upstream's CI
  sees; the run shadows (everything runs, cight reports what it would have run). Each new head
  upstream is a new push here. Closed upstream -> closed here.

Upstream is never written to: nothing here names an upstream PR as `owner/repo#N` or by URL
(GitHub would add a back-link to its timeline) and no upstream text with @mentions is copied.

Mirror branches run upstream contributors' code in a same-repository workflow, so:
- .github/workflows on a mirror branch is main's, except test.yml regenerated from the PR's own
  test.yml (a PR's other workflow edits or new workflow files never run here);
- the App's key lives in an environment that only main may use (see README.md).
"""
import argparse
import fnmatch
import json
import os
import re
import subprocess
import sys
import tempfile
from datetime import datetime, timedelta, timezone

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import workflow  # noqa: E402

UPSTREAM = os.environ.get("MIRROR_UPSTREAM", "immich-app/immich")
FORK = os.environ.get("GITHUB_REPOSITORY", "aBraM-aBraM/immich")
TEST_YML = ".github/workflows/test.yml"
# workflows that stay enabled here; any other (one upstream adds later) is disabled after a sync
ALLOWED_WORKFLOWS = {TEST_YML, ".github/workflows/cight-mirror.yml"}
# pre-job filters whose jobs run here: a PR that matches none of them runs nothing upstream's
# e2e jobs would, so it is not mirrored
E2E_FILTERS = ["e2e", "server", "cli", "web"]
SINCE_DAYS = int(os.environ.get("MIRROR_SINCE_DAYS", "3"))  # only PRs updated this recently
MAX_PUSHES = int(os.environ.get("MIRROR_MAX_PUSHES", "8"))  # per run: runner concurrency
TRAILER_PR, TRAILER_HEAD, TRAILER_MAIN = "Upstream-PR", "Upstream-Head", "Upstream-Main"

DRY = False
MAIN = None  # the main mirrors build on: main as sync left it (local in a dry run)


def log(msg):
    print(msg, flush=True)


def git(*args, check=True, capture=True):
    r = subprocess.run(["git", *args], text=True, capture_output=capture)
    if check and r.returncode != 0:
        raise RuntimeError(f"git {' '.join(args)}: {r.stderr.strip() or r.stdout.strip()}")
    return r.stdout.strip() if capture else ""


def gh_json(path, paginate=False):
    args = ["gh", "api", "-H", "Accept: application/vnd.github+json", path]
    if paginate:  # one item per line, every page (works on gh versions without --slurp)
        args[2:2] = ["--paginate", "--jq", ".[] | tojson"]
    r = subprocess.run(args, text=True, capture_output=True)
    if r.returncode != 0:
        raise RuntimeError(f"gh api {path}: {r.stderr.strip()}")
    if paginate:
        return [json.loads(line) for line in r.stdout.splitlines() if line.strip()]
    return json.loads(r.stdout)


def gh_write(*args):
    if DRY:
        log(f"  [dry-run] gh {' '.join(args)}")
        return ""
    r = subprocess.run(["gh", *args], text=True, capture_output=True)
    if r.returncode != 0:
        raise RuntimeError(f"gh {' '.join(args)}: {r.stderr.strip()}")
    return r.stdout.strip()


def push(*args):
    if DRY:
        log(f"  [dry-run] git push {' '.join(args)}")
        return
    git("push", *args)


def show(rev, path):
    r = subprocess.run(["git", "show", f"{rev}:{path}"], text=True, capture_output=True)
    return r.stdout if r.returncode == 0 else None


def fetch_upstream():
    url = f"https://github.com/{UPSTREAM}.git"
    git("fetch", "--quiet", "--filter=blob:none", url, "+refs/heads/main:refs/mirror/upstream/main")
    return git("rev-parse", "refs/mirror/upstream/main")


def generated(text, what):
    try:
        return workflow.transform(text)
    except workflow.Shape as e:
        raise RuntimeError(f"{what}: upstream's test.yml changed shape, update workflow.py: {e}")


def merge_in(rev, message, upstream_test_yml, what, workflows):
    """Merge `rev` into HEAD with test.yml regenerated from `upstream_test_yml`. Other
    workflows: `theirs` (a sync: upstream's own, merged as they are; disabled here) or `ours`
    (a mirror PR: main's, every file, new ones dropped, so a PR's workflow code never runs
    here). False (merge aborted) on a conflict outside .github/workflows."""
    r = subprocess.run(["git", "merge", "--no-ff", "--no-commit", "--quiet", rev], text=True, capture_output=True)
    conflicts = set(git("diff", "--name-only", "--diff-filter=U").splitlines())
    if r.returncode != 0 and not conflicts:
        git("merge", "--abort", check=False)
        raise RuntimeError(f"{what}: git merge: {r.stderr.strip()}")
    others = {c for c in conflicts if not c.startswith(".github/workflows/")}
    if others:
        git("merge", "--abort")
        log(f"  {what}: conflicts outside .github/workflows ({', '.join(sorted(others))}): skipped")
        return False
    if workflows == "ours":
        git("checkout", "HEAD", "--", ".github/workflows")
        added = git("diff", "--cached", "--name-only", "--diff-filter=A", "HEAD", "--",
                    ".github/workflows").splitlines()
        for f in added:
            git("rm", "--quiet", "--cached", "--force", "--", f)
            if os.path.exists(f):
                os.remove(f)
    else:
        for f in conflicts - {TEST_YML}:
            git("checkout", "--theirs", "--", f)
            git("add", "--", f)
    with open(TEST_YML, "w") as fh:
        fh.write(generated(upstream_test_yml, what))
    git("add", TEST_YML)
    git("commit", "--quiet", "--no-verify", "-m", message)
    return True


def sync():
    """main <- upstream main. Returns the upstream commit main now contains."""
    log("sync: main <- upstream main")
    up = fetch_upstream()
    git("fetch", "--quiet", "origin", "+refs/heads/main:refs/remotes/origin/main")
    git("checkout", "--quiet", "-B", "main", "origin/main")
    up_yml = show(up, TEST_YML)
    if subprocess.run(["git", "merge-base", "--is-ancestor", up, "HEAD"]).returncode == 0:
        # upstream has nothing new; still regenerate test.yml (workflow.py may have changed)
        want = generated(up_yml, "sync")
        if show("HEAD", TEST_YML) == want:
            log(f"  up to date with upstream {up[:12]}")
            set_main()
            return up
        with open(TEST_YML, "w") as fh:
            fh.write(want)
        git("add", TEST_YML)
        git("commit", "--quiet", "-m", f"mirror: test.yml regenerated (workflow.py)\n\n{TRAILER_MAIN}: {up}")
    else:
        msg = f"mirror: upstream main at {up[:12]}\n\n{TRAILER_MAIN}: {up}"
        if not merge_in(up, msg, up_yml, "sync", workflows="theirs"):
            raise RuntimeError("sync: upstream main conflicts with main outside .github/workflows; resolve by hand")
        log(f"  merged upstream {up[:12]}")
    push("origin", "HEAD:refs/heads/main")
    set_main()
    disable_new_workflows()
    return up


def set_main():
    global MAIN
    MAIN = git("rev-parse", "HEAD")


def disable_new_workflows():
    for w in gh_json(f"repos/{FORK}/actions/workflows?per_page=100", paginate=False)["workflows"]:
        if w["state"] == "active" and w["path"] not in ALLOWED_WORKFLOWS:
            log(f"  disabling {w['path']} (new upstream workflow)")
            gh_write("api", "-X", "PUT", f"repos/{FORK}/actions/workflows/{w['id']}/disable")


def e2e_patterns(test_yml):
    """The pre-job's filters for the jobs that run here, and its force-filters."""
    pats, cur, section = [], None, None
    for line in test_yml.splitlines():
        s = line.strip()
        if re.match(r"^\s*filters:\s*\|", line):
            section = "filters"
            continue
        if re.match(r"^\s*force-filters:\s*\|", line):
            section = "force"
            continue
        if section and re.match(r"^\s*[\w-]+:\s", line) and not s.startswith("- "):
            section = None
        if section == "filters":
            m = re.match(r"^\s*([\w.-]+):\s*$", line)
            if m:
                cur = m.group(1)
            elif s.startswith("- ") and cur in E2E_FILTERS:
                pats.append(s[2:].strip("'\""))
        elif section == "force" and s.startswith("- "):
            pats.append(s[2:].strip("'\""))
    if not pats:
        raise RuntimeError("no pre-job filters found in test.yml")
    return pats


def matches(path, pats):
    return any(fnmatch.fnmatch(path, p) or (p.endswith("/**") and path.startswith(p[:-2])) for p in pats)


def safe_title(n, title):
    title = title.replace("@", "@​")  # no mentions
    title = re.sub(r"(?<![\w/])#(\d)", r"# \1", title)  # no references into this fork's numbers
    return f"upstream PR {n}: {title}"[:240]


def mirrored():
    """{N: (upstream head mirrored, branch tip)} for the mirror branches here."""
    git("fetch", "--quiet", "--prune", "--filter=blob:none", "origin",
        "+refs/heads/mirror/*:refs/remotes/origin/mirror/*")
    out = {}
    for ref in git("for-each-ref", "--format=%(refname:short)", "refs/remotes/origin/mirror/").splitlines():
        m = re.match(r"^origin/mirror/pr-(\d+)$", ref)
        if not m:
            continue
        head = git("log", "-1", f"--format=%(trailers:key={TRAILER_HEAD},valueonly)", ref).strip()
        out[int(m.group(1))] = head
    return out


def fork_prs():
    """{branch: number} of open mirror PRs here."""
    prs = gh_json(f"repos/{FORK}/pulls?state=open&per_page=100", paginate=True)
    return {p["head"]["ref"]: p["number"] for p in prs if p["head"]["ref"].startswith("mirror/pr-")}


def prs():
    log("prs: mirror upstream's open pull requests")
    up = fetch_upstream()
    if MAIN is None:
        git("fetch", "--quiet", "origin", "+refs/heads/main:refs/remotes/origin/main")
    main = MAIN or git("rev-parse", "origin/main")
    # the newest upstream commit main contains: what this PR is compared against upstream-side
    base_up = git("merge-base", main, up)
    base_yml = show(base_up, TEST_YML)
    pats = e2e_patterns(base_yml)

    open_up = gh_json(f"repos/{UPSTREAM}/pulls?state=open&per_page=100", paginate=True)
    open_nums = {p["number"] for p in open_up}
    done = mirrored()
    here = fork_prs()
    since = datetime.now(timezone.utc) - timedelta(days=SINCE_DAYS)

    todo = []
    for p in open_up:
        n, head = p["number"], p["head"]["sha"]
        if p["base"]["ref"] != "main":
            continue
        if done.get(n) == head:
            continue
        if n not in done and datetime.fromisoformat(p["updated_at"].replace("Z", "+00:00")) < since:
            continue  # an old PR not mirrored yet: not worth a run until it moves
        todo.append(p)
    # people's PRs first (their in-progress pushes are where real failures turn up), then
    # bots' (Renovate, translations: they update constantly and would take every slot); each
    # group newest first
    todo.sort(key=lambda p: p["updated_at"], reverse=True)
    todo.sort(key=lambda p: p["user"]["type"] == "Bot" or p["user"]["login"].endswith("[bot]"))

    pushed = 0
    for p in todo:
        if pushed >= MAX_PUSHES:
            log(f"  {len(todo) - pushed} more waiting for the next run (MIRROR_MAX_PUSHES={MAX_PUSHES})")
            break
        n, head = p["number"], p["head"]["sha"]
        files = [f["filename"] for f in gh_json(f"repos/{UPSTREAM}/pulls/{n}/files?per_page=100", paginate=True)]
        if not any(matches(f, pats) for f in files):
            continue
        if mirror_one(n, head, main, base_up, base_yml, p["title"], here):
            pushed += 1

    # closed upstream -> closed here
    for branch, num in here.items():
        n = int(branch.rsplit("-", 1)[1])
        if n not in open_nums:
            log(f"  upstream PR {n} closed: closing #{num} here")
            gh_write("pr", "close", str(num), "-R", FORK, "--delete-branch")
    log(f"  {pushed} pushed")


def mirror_one(n, head, main, base_up, base_yml, title, here):
    what = f"upstream PR {n} at {head[:12]}"
    try:
        git("fetch", "--quiet", "--filter=blob:none", f"https://github.com/{UPSTREAM}.git",
            f"+refs/pull/{n}/head:refs/mirror/upstream/pr/{n}")
    except RuntimeError as e:
        log(f"  {what}: fetch failed: {e}")
        return False
    got = git("rev-parse", f"refs/mirror/upstream/pr/{n}")
    if got != head:
        log(f"  {what}: moved to {got[:12]} while listing; mirroring that")
        head = got

    # test.yml as upstream would have it with this PR merged: the PR's edit, if any, on top of
    # the upstream commit main contains
    mb = git("merge-base", base_up, head)
    pr_yml, mb_yml = show(head, TEST_YML), show(mb, TEST_YML)
    up_yml = base_yml
    if pr_yml != mb_yml:
        if pr_yml is None:
            log(f"  {what}: deletes test.yml: skipped")
            return False
        with tempfile.TemporaryDirectory() as d:
            paths = []
            for name, text in (("ours", base_yml), ("base", mb_yml or ""), ("theirs", pr_yml)):
                path = os.path.join(d, name)
                with open(path, "w") as fh:
                    fh.write(text)
                paths.append(path)
            r = subprocess.run(["git", "merge-file", "-p", *paths], text=True, capture_output=True)
            if r.returncode != 0:
                log(f"  {what}: its test.yml conflicts with upstream main's: skipped")
                return False
            up_yml = r.stdout

    branch = f"mirror/pr-{n}"
    git("checkout", "--quiet", "-B", branch, main)
    msg = (f"mirror: upstream PR {n} at {head[:12]}\n\n"
           f"Mirrors upstream's pull request for cight's shadow record; not for review.\n\n"
           f"{TRAILER_PR}: {n}\n{TRAILER_HEAD}: {head}")
    try:
        ok = merge_in(head, msg, up_yml, what, workflows="ours")
    except RuntimeError as e:
        log(f"  {e}: skipped")
        git("merge", "--abort", check=False)
        return False
    if not ok:
        return False
    push("--force", "origin", f"HEAD:refs/heads/{branch}")
    log(f"  {what} -> {branch}")
    if branch not in here:
        body = (f"Mirror of upstream pull request {n} (head `{head[:12]}`), merged into this fork's "
                f"main, so its e2e run here records what cight would have selected (shadow mode: "
                f"every test runs).\n\nOpened by `.github/cight/mirror.py`; closed when upstream's "
                f"is. Not for review or merge.")
        gh_write("pr", "create", "-R", FORK, "--head", branch, "--base", "main",
                 "--title", safe_title(n, title), "--body", body)
    return True


def main():
    global DRY
    ap = argparse.ArgumentParser()
    ap.add_argument("--dry-run", action="store_true", help="merge locally, push and write nothing")
    ap.add_argument("what", choices=["sync", "prs", "all"])
    a = ap.parse_args()
    DRY = a.dry_run
    if git("status", "--porcelain"):
        sys.exit("mirror.py: the working tree is not clean")
    try:
        if a.what in ("sync", "all"):
            sync()
        if a.what in ("prs", "all"):
            prs()
    except RuntimeError as e:
        sys.exit(f"mirror.py: {e}")


if __name__ == "__main__":
    main()
